import {Card, type CardProps, rem, useTheme} from '@sanity/ui'
import {useVirtualizer, type VirtualItem} from '@tanstack/react-virtual'
import {isValid} from 'date-fns/isValid'
import get from 'lodash-es/get.js'
import {type CSSProperties, type ElementType, Fragment, useMemo} from 'react'
import {Text, Box, Flex} from 'ui5'

import {TooltipDelayGroupProvider} from '../../../../../ui-components/tooltipDelayGroupProvider/TooltipDelayGroupProvider'
import {TableEmptyState} from './TableEmptyState'
import {TableHeader} from './TableHeader'
import {TableLayout} from './TableLayout'
import {TableProvider, type TableSort, useTableContext} from './TableProvider'
import {
  TABLE_ROW_ACTIONS_WIDTH,
  type Column,
  type HeaderProps,
  type InjectedTableProps,
  type TableRowActions,
} from './types'

type RowDatum<TableData, AdditionalRowTableData> = (AdditionalRowTableData extends undefined
  ? TableData
  : TableData & AdditionalRowTableData) & {isLoading?: boolean}

export type TableRowProps = CardProps<ElementType>

type VirtualDatum = {
  virtualRow: VirtualItem
  index: number
  isFirst: boolean
  isLast: boolean
}

export interface TableProps<TableData, AdditionalRowTableData> {
  columnDefs: Column<RowDatum<TableData, AdditionalRowTableData>>[]
  searchFilter?: (data: TableData[], searchTerm: string) => TableData[]
  data: TableData[]
  emptyState: (() => React.JSX.Element) | string
  loading?: boolean
  /**
   * Should be the dot separated path to the unique identifier of the row. e.g. document._id
   */
  rowId: string
  rowActions?: TableRowActions
  rowProps?: (datum: TableData) => Partial<TableRowProps>
  scrollContainerRef: HTMLDivElement | null
  hideTableInlinePadding?: boolean
}

const ITEM_HEIGHT = 59
const LOADING_ROW_COUNT = 3

function RowActionsHeader({headerProps}: HeaderProps) {
  return (
    <Flex {...headerProps} paddingY={3} paddingX={3}>
      <Text muted size={1} weight="medium" as="div" trim={true}>
        &nbsp;
      </Text>
    </Flex>
  )
}

function RowActionsCell(props: {
  datum: {isLoading?: boolean}
  cellProps: InjectedTableProps
  sorting: boolean
}) {
  const {datum, cellProps} = props
  const {rowActions} = useTableContext()

  return (
    <Flex
      {...cellProps}
      alignItems="center"
      flexBasis="auto"
      flexGrow={0}
      flexShrink={0}
      padding={3}
    >
      {(!datum.isLoading && rowActions?.({datum})) || <Box style={{width: '25px'}} />}
    </Flex>
  )
}

const ROW_ACTIONS_COLUMN_DEF: Column = {
  id: 'actions',
  sorting: false,
  // Header and body are independent flexboxes — keep this gutter the same width in both.
  width: TABLE_ROW_ACTIONS_WIDTH,
  header: RowActionsHeader,
  cell: RowActionsCell,
}

const TableInner = <TableData, AdditionalRowTableData>({
  columnDefs,
  data,
  emptyState,
  searchFilter,
  rowId,
  loading = false,
  rowProps = () => ({}),
  scrollContainerRef,
  hideTableInlinePadding = false,
}: TableProps<TableData, AdditionalRowTableData>) => {
  const {searchTerm, sort, rowActions} = useTableContext()

  const filteredData = useMemo(() => {
    const filteredResult = searchFilter ? searchFilter(data, searchTerm || '') : data
    if (!sort) return filteredResult

    const sortColumn = columnDefs.find((column) => column.id === sort.column)
    return [...filteredResult].sort((a, b) => {
      let order: number

      const [aValue, bValue]: (number | string)[] = [a, b].map(
        (sortValue) =>
          sortColumn?.sortTransform?.(
            sortValue as RowDatum<TableData, AdditionalRowTableData>,
            sort.direction,
          ) ?? get(sortValue, sort.column),
      )
      if (
        typeof aValue === 'string' &&
        typeof bValue === 'string' &&
        !isValid(aValue) &&
        !isValid(bValue)
      ) {
        order = aValue.toLowerCase().localeCompare(bValue.toLowerCase())
      } else {
        const parseDate = (datum: number | string) => {
          if (sortColumn?.sortTransform && typeof datum === 'number') return datum

          return typeof datum === 'string' ? Date.parse(datum) : 0
        }

        const [aDate, bDate] = [aValue, bValue].map(parseDate)

        order = aDate - bDate
      }

      if (sort.direction === 'asc') return order
      return -order
    })
  }, [columnDefs, data, searchFilter, searchTerm, sort])

  // oxlint-disable-next-line react/incompatible-library -- pre-existing violation, to be fixed in a follow-up
  const rowVirtualizer = useVirtualizer({
    count: filteredData.length,
    getScrollElement: () => scrollContainerRef,
    estimateSize: () => ITEM_HEIGHT,
    overscan: 5,
  })

  const amalgamatedColumnDefs = useMemo(
    () =>
      (rowActions ? [...columnDefs, ROW_ACTIONS_COLUMN_DEF] : columnDefs).filter(
        (column) => !column.hidden,
      ),
    [columnDefs, rowActions],
  )

  const tableMinWidth = useMemo(
    () => amalgamatedColumnDefs.reduce((sum, col) => sum + (col.width || 200), 0),
    [amalgamatedColumnDefs],
  )

  const renderRow = (
    datum: VirtualDatum &
      (TableData | (TableData & AdditionalRowTableData) | {_id: string; isLoading: boolean}),
  ) => {
    const {style: rowPropsStyle, ...cardRowProps} = rowProps(datum as TableData)
    const cardKey = loading ? `skeleton-${datum.index}` : String(get(datum, rowId))

    return (
      <Card
        key={cardKey}
        data-testid={loading ? 'table-row-skeleton' : 'table-row'}
        borderBottom
        display="flex"
        data-index={datum.index}
        as="tr"
        style={{
          height: `${datum.virtualRow.size}px`,
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          transform: `translateY(${datum.virtualRow.start}px)`,
          paddingInline: 'var(--tableInlinePadding)',
          // Consumer-supplied row styles are merged (not clobbered) so they can tint/flag a row
          // without dropping the virtualization layout (height/position/transform).
          ...rowPropsStyle,
        }}
        {...cardRowProps}
      >
        {amalgamatedColumnDefs.map(({cell: Cell, style, width, id, sorting = false}) => (
          <Fragment key={String(id)}>
            <Cell
              datum={{...datum, isLoading: loading} as RowDatum<TableData, AdditionalRowTableData>}
              cellProps={{
                as: 'td',
                id: String(id),
                style: {...style, width: width || undefined},
              }}
              sorting={sorting}
            />
          </Fragment>
        ))}
      </Card>
    )
  }

  const emptyContent = useMemo(
    () => <TableEmptyState emptyState={emptyState} colSpan={amalgamatedColumnDefs.length} />,
    [amalgamatedColumnDefs.length, emptyState],
  )

  const headers = useMemo(
    () =>
      amalgamatedColumnDefs.map(({cell, sortTransform, ...header}) => ({
        ...header,
        id: String(header.id),
      })),
    [amalgamatedColumnDefs],
  )

  const theme = useTheme()
  const maxInlineSize = (!hideTableInlinePadding && theme.sanity.v2?.container[3]) || 0
  const paddingInline = rem(theme.sanity.v2?.space[3] ?? 0)
  const tableInlinePadding = hideTableInlinePadding
    ? '0px'
    : `max(${paddingInline}, calc((100% - var(--maxInlineSize)) / 2))`

  const renderLoadingRows = (
    rowRenderer: (
      datum: VirtualDatum &
        ({_id: string; isLoading: boolean} | TableData | (TableData & AdditionalRowTableData)),
    ) => React.ReactNode,
  ) => {
    return Array.from({length: LOADING_ROW_COUNT}).map((_el, index) => {
      const cardKey = `skeleton-${index}`
      const virtualRow: VirtualItem = {
        index,
        start: index * ITEM_HEIGHT,
        size: ITEM_HEIGHT,
        lane: 0,
        key: cardKey,
        end: index * ITEM_HEIGHT + ITEM_HEIGHT,
      }

      return rowRenderer({
        _id: cardKey,
        isLoading: true,
        virtualRow,
        index,
        isFirst: index === 0,
        isLast: index === LOADING_ROW_COUNT - 1,
      })
    })
  }

  const tableContent = () => {
    if (loading) {
      return renderLoadingRows(renderRow)
    }

    if (filteredData.length === 0) {
      return emptyContent
    }

    return rowVirtualizer.getVirtualItems().map((virtualRow, index) => {
      const datum = filteredData[virtualRow.index]
      return renderRow({
        ...datum,
        virtualRow,
        index,
        isFirst: virtualRow.index === 0,
        isLast: virtualRow.index === filteredData.length - 1,
      })
    })
  }

  return (
    <div style={{height: '100%'}}>
      <div
        style={
          {
            'width': '100%',
            'minWidth': `${tableMinWidth}px`,
            'height': '100%',
            'position': 'relative',
            '--maxInlineSize': rem(maxInlineSize),
            '--tableInlinePadding': tableInlinePadding,
          } as CSSProperties
        }
      >
        <TableLayout
          isEmptyState={filteredData.length === 0 && !loading}
          header={
            <TableHeader
              headers={headers}
              searchDisabled={loading || (!searchTerm && !data.length)}
            />
          }
          content={tableContent()}
          contentHeight={`${rowVirtualizer.getTotalSize()}px`}
        />
      </div>
    </div>
  )
}

export const Table = <TableData, AdditionalRowTableData = undefined>({
  defaultSort,
  ...props
}: TableProps<TableData, AdditionalRowTableData> & {defaultSort?: TableSort}) => {
  return (
    <TooltipDelayGroupProvider>
      <TableProvider defaultSort={defaultSort} rowActions={props.rowActions}>
        <TableInner<TableData, AdditionalRowTableData> {...props} />
      </TableProvider>
    </TooltipDelayGroupProvider>
  )
}
